  "con-09-sync-transfer.json": {
    "schemaVersion": "con-09-sync-transfer.v1",
    "license": "Apache-2.0",
    "authority": "Design registry04 sections 4-5 and contracts07 section 5; transfer-ticket shape cases are executable Foundation evidence, sync/resource/realm-transfer owner vectors are declarative and not executed by CON.09",
    "transferTicket": {
      "sample": {
        "ticketId": {
          "value": "ABEiM0RVZneImaq7zN3u/w=="
        },
        "url": "https://objects.example.invalid/ticket/opaque-route",
        "expiresAt": {
          "unixSeconds": "3600",
          "nanos": 0
        },
        "resourceId": {
          "value": "ESIzRFVmd4iZqrvM3e7/AA=="
        },
        "range": {
          "offset": "0",
          "length": "8388608"
        },
        "maxPartBytes": 8388608
      },
      "cases": [
        {
          "id": "con09-transfer-ticket-valid-bounded-range",
          "target": "TransferTicket",
          "sample": "TransferTicket",
          "valid": true
        },
        {
          "id": "con09-transfer-ticket-valid-whole-object-route",
          "target": "TransferTicket",
          "sample": "TransferTicket",
          "remove": [
            "range"
          ],
          "valid": true
        },
        {
          "id": "con09-transfer-ticket-requires-route",
          "target": "TransferTicket",
          "sample": "TransferTicket",
          "remove": [
            "url"
          ],
          "valid": false
        },
        {
          "id": "con09-transfer-ticket-requires-part-limit",
          "target": "TransferTicket",
          "sample": "TransferTicket",
          "remove": [
            "maxPartBytes"
          ],
          "valid": false
        },
        {
          "id": "con09-transfer-ticket-rejects-zero-part-limit",
          "target": "TransferTicket",
          "sample": "TransferTicket",
          "set": {
            "maxPartBytes": 0
          },
          "valid": false
        },
        {
          "id": "con09-transfer-ticket-rejects-part-limit-over-eight-mib",
          "target": "TransferTicket",
          "sample": "TransferTicket",
          "set": {
            "maxPartBytes": 8388609
          },
          "valid": false
        },
        {
          "id": "con09-transfer-ticket-rejects-storage-credential-extension",
          "target": "TransferTicket",
          "sample": "TransferTicket",
          "set": {
            "r2Credentials": {
              "accessKeyId": "not-a-public-contract-field",
              "secretAccessKey": "not-a-public-contract-field"
            }
          },
          "valid": false
        }
      ]
    },
    "syncTransferVectors": [
      {
        "id": "con09-sync-stale-revision-preserves-conflict-proposal",
        "evidenceClass": "declarative-owner-runtime-vector-not-executed-by-con09",
        "operation": "sync.pushChange",
        "given": {
          "baseRevision": "17",
          "currentRevision": "18",
          "proposalHash": "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"
        },
        "expect": {
          "result": "revision-conflict",
          "proposalPreserved": true,
          "ownerMutation": false
        }
      },
      {
        "id": "con09-resource-absent-hash-never-promotes",
        "evidenceClass": "declarative-owner-runtime-vector-not-executed-by-con09",
        "operation": "resource.completeUpload",
        "given": {
          "expectedContentHash": null,
          "allPartsPresent": true
        },
        "expect": {
          "verified": false,
          "ownerPinCreated": false
        }
      },
      {
        "id": "con09-resource-expired-pin-blocks-adoption",
        "evidenceClass": "declarative-owner-runtime-vector-not-executed-by-con09",
        "ownerBoundary": "verified-resource adoption",
        "given": {
          "pinExpired": true,
          "contentHashPresent": true
        },
        "expect": {
          "ownerAdoption": false,
          "verifiedObjectRetained": true
        }
      },
      {
        "id": "con09-transfer-exclusions-are-per-root-issues",
        "evidenceClass": "declarative-owner-runtime-vector-not-executed-by-con09",
        "operation": "transfer.requestExport",
        "given": {
          "includedRoots": [
            "conversation",
            "memory",
            "scopeSession"
          ],
          "excludedAuthority": [
            "credentials",
            "deviceTrust",
            "activeExecution",
            "policy",
            "deletionTombstones"
          ]
        },
        "expect": {
          "manifestRootsContainOnlyIncludedRoots": true,
          "exclusionsUseTransferJobIssues": true,
          "inventedExcludedRootsField": false
        }
      },
      {
        "id": "con09-transfer-resume-uses-bounded-root-mappings",
        "evidenceClass": "declarative-owner-runtime-vector-not-executed-by-con09",
        "operation": "transfer.commitImport",
        "given": {
          "requestRootLimit": 100,
          "committedRoots": 1,
          "totalRoots": 2,
          "mappings": [
            "committed",
            "planned"
          ],
          "previewHashBound": true
        },
        "expect": {
          "resumeUsesSameTargetIds": true,
          "dependentRootsRemainHiddenUntilCommitted": true,
          "workspaceWideAtomicityClaim": false
        }
      }
    ]
  },
